private val swLower by lazy {
    swCatalog.keys().asSequence().associate { it.lowercase() to swCatalog.getString(it) }
}

fun tr(text: String): String {
    if (AppLanguage != "sw") return text
    val clean = text.trim().replace(Regex("""\s+"""), " ")
    val translated = swCatalog.optString(clean, "").ifBlank { swLower[clean.lowercase()] ?: "" }
    if (translated.isNotBlank())
        return text.replace(
            text.trim(),
            if (clean == clean.uppercase()) translated.uppercase() else translated,
        )
    return text
}
